shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tokio-util/tests/time_delay_queue.rs
+++ b/tokio-util/tests/time_delay_queue.rs
@@ -169,6 +169,40 @@
 }

 #[tokio::test]
+async fn remove_last_item_wakes_poller() {
+    time::pause();
+
+    let mut queue = task::spawn(DelayQueue::new());
+    let key = queue.insert("foo", ms(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key).into_inner(), "foo");
+
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test]
+async fn try_remove_last_item_wakes_poller() {
+    time::pause();
+
+    let mut queue = task::spawn(DelayQueue::new());
+    let key1 = queue.insert("foo", ms(100));
+    let key2 = queue.insert("bar", ms(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.try_remove(&key1).unwrap().into_inner(), "foo");
+    assert!(!queue.is_woken());
+    assert!(queue.try_remove(&key1).is_none());
+    assert!(!queue.is_woken());
+    assert_eq!(queue.try_remove(&key2).unwrap().into_inner(), "bar");
+
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test]
 async fn reset_entry() {
     time::pause();
PATCH
cargo test --offline --test time_delay_queue --features full last_item_wakes_poller

